async () => {
const g=document.querySelector('vaadin-grid');
const seen=new Map();
for(let i=0;i<200;i++){
 g.shadowRoot.querySelectorAll('tr').forEach(r=>{const c=[...r.querySelectorAll('td')].map(t=>t.innerText.trim());if(c.length>=5)seen.set(c[2],c)});
 const before=g.scrollTop;
 g.$.table.scrollTop+=400;
 await new Promise(r=>setTimeout(r,150));
 if(i>5&&g.$.table.scrollTop===before&&false)break;
}
const rows=[...seen.values()];
return {total:rows.length,count:rows.filter(c=>c[4].includes("Linens")&&c[3]==="Imported lead").length}
}

